  ('60111111-1111-4111-8111-111111111111','50111111-1111-4111-8111-111111111111',1,'mcq','Which HTTP method is best for creating a new resource?','REST basics',1,0,'easy',45,ARRAY['api','http'],'Use POST for create operations.','["GET","POST","PUT","DELETE"]'::jsonb,'"POST"'::jsonb,'{"topic":"rest"}'::jsonb),
  ('60111111-1111-4111-8111-111111111112','50111111-1111-4111-8111-111111111111',2,'mcq','Which database constraint prevents duplicate values in a column?','SQL basics',1,0,'easy',45,ARRAY['sql'],'Use UNIQUE to enforce uniqueness.','["PRIMARY KEY","UNIQUE","FOREIGN KEY","CHECK"]'::jsonb,'"UNIQUE"'::jsonb,'{"topic":"sql"}'::jsonb),
  ('60111111-1111-4111-8111-111111111113','50111111-1111-4111-8111-111111111111',3,'short_answer','Name one reliability pattern for services.','System design',1,0,'medium',60,ARRAY['reliability'],'Retries and circuit breakers are common patterns.','[]'::jsonb,'"retry"'::jsonb,'{"topic":"reliability"}'::jsonb),
  ('60111111-1111-4111-8111-111111111114','50111111-1111-4111-8111-111111111111',4,'mcq','What is a common benefit of indexing?','Performance',1,0,'medium',45,ARRAY['sql','performance'],'Indexes speed up lookups.','["Faster reads","Slower writes","More storage only","No effect"]'::jsonb,'"Faster reads"'::jsonb,'{"topic":"indexing"}'::jsonb),
  ('60111111-1111-4111-8111-111111111115','50111111-1111-4111-8111-111111111111',5,'mcq','Which tool is commonly used to run background jobs?','Ops basics',1,0,'medium',45,ARRAY['ops'],'Queues are a common pattern.','["Redis","Kafka","Cron","All of the above"]'::jsonb,'"All of the above"'::jsonb,'{"topic":"queue"}'::jsonb),
  ('60111111-1111-4111-8111-111111111116','50111111-1111-4111-8111-111111111111',6,'true_false','A database transaction should be atomic.','Transactions',1,0,'easy',30,ARRAY['sql'],'Atomicity ensures all-or-nothing behavior.','[]'::jsonb,'true'::jsonb,'{"topic":"transactions"}'::jsonb),
  ('60111111-1111-4111-8111-111111111117','50111111-1111-4111-8111-111111111111',7,'long_answer','Describe the difference between horizontal and vertical scaling.','Scaling',1,0,'hard',90,ARRAY['scaling'],'Horizontal adds more machines; vertical adds more power to one machine.','[]'::jsonb,'"horizontal"'::jsonb,'{"topic":"scaling"}'::jsonb),
  ('60111111-1111-4111-8111-111111111118','50111111-1111-4111-8111-111111111111',8,'mcq','Which metric is commonly used to track API latency?','SRE basics',1,0,'medium',45,ARRAY['sre'],'Latency tracks response time.','["CPU percentage","P95 latency","Disk usage","Open files"]'::jsonb,'"P95 latency"'::jsonb,'{"topic":"latency"}'::jsonb),
  ('60111111-1111-4111-8111-111111111119','50111111-1111-4111-8111-111111111111',9,'mcq','What is the main role of an API gateway?','Architecture',1,0,'medium',45,ARRAY['api'],'An API gateway routes and filters requests.','["Store data","Route traffic","Render UI","Compile code"]'::jsonb,'"Route traffic"'::jsonb,'{"topic":"gateway"}'::jsonb),
  ('60111111-1111-4111-8111-11111111111a','50111111-1111-4111-8111-111111111111',10,'short_answer','Name one tool used for observability.','Observability',1,0,'easy',45,ARRAY['observability'],'Prometheus and Grafana are common observability tools.','[]'::jsonb,'"prometheus"'::jsonb,'{"topic":"observability"}'::jsonb),
  ('60122222-2222-4222-8222-222222222221','50122222-2222-4222-8222-222222222222',1,'mcq','Which metric best measures user retention?','Product metrics',1,0,'easy',45,ARRAY['metrics'],'Retention tracks repeat usage.','["Bounce rate","Retention rate","Page views","CTR"]'::jsonb,'"Retention rate"'::jsonb,'{"topic":"retention"}'::jsonb),
